// DebugBuddy — Session State
const sd = $getWorkflowStaticData('global');
if (!sd.sessions) sd.sessions = {};

const sessionId = $json.sessionId || 'default';
const message = ($json.chatInput || '').trim();

let s = sd.sessions[sessionId];
if (!s || s.completed) {
  s = { original_report: message, clarification_answers: [], iteration: 1, completed: false };
} else {
  s.clarification_answers.push({ turn: s.iteration, answer: message });
  s.iteration = s.iteration + 1;
}
sd.sessions[sessionId] = s;

let full = 'ORIGINAL REPORT:\n' + s.original_report;
if (s.clarification_answers.length > 0) {
  full += '\n\nANSWERS THE REPORTER HAS SINCE PROVIDED:';
  for (const a of s.clarification_answers) {
    full += '\n- (round ' + a.turn + ') ' + a.answer;
  }
}

return [{ json: {
  sessionId,
  original_report: s.original_report,
  clarification_answers: s.clarification_answers,
  iteration: s.iteration,
  full_report_text: full
} }];

// DebugBuddy — Context Builder
const intake = $json.output || {};
const sess = $('Session State').first().json;
return [{ json: { ...sess, intake: {
  summary: intake.summary,
  category: intake.category,
  severity: intake.severity,
  known_information: intake.known_information || {},
  requires_clarification: intake.requires_clarification
} } }];

