// DebugBuddy — Readiness Evaluator
const MAX_ITERATIONS = 3;
const planner = $json.output || {};
const ctx = $('Context Builder').first().json;

const score = typeof planner.readiness_score === 'number' ? planner.readiness_score : 0;
let ready = score >= 60;
let forced = false;
if (!ready && ctx.iteration >= MAX_ITERATIONS) { ready = true; forced = true; }

return [{ json: { ...ctx, ready, forced,
  readiness_score: score,
  confidence: typeof planner.confidence === 'number' ? planner.confidence : 0,
  missing_information: planner.missing_information || [] } }];

