// DebugBuddy — Report Formatter (code, not AI)
const sess = $('Session State').first().json;
const ev = $('Readiness Evaluator').first().json;
const r = $json.output || {};

const sd = $getWorkflowStaticData('global');
if (sd.sessions && sd.sessions[sess.sessionId]) {
  sd.sessions[sess.sessionId].completed = true;
}

const bullets = (arr) => (arr && arr.length)
  ? arr.map(x => '- ' + x).join('\n')
  : '_None recorded._';
const numbered = (arr) => (arr && arr.length)
  ? arr.map((x, i) => (i + 1) + '. ' + x).join('\n')
  : '_None recorded._';
const checks = (arr) => (arr && arr.length)
  ? arr.map(x => '- [ ] ' + x).join('\n')
  : '_None recorded._';

let out = '# Engineering Report\n\n';
out += '## Executive Summary\n' + (r.executive_summary || '_Not provided._') + '\n\n';

const sev = r.severity || ev.intake?.severity;
const sub = r.likely_subsystem;
const meta = [];
if (sev) meta.push('**Severity:** ' + sev);
if (sub) meta.push('**Likely subsystem:** ' + sub);
if (ev.intake?.category) meta.push('**Category:** ' + ev.intake.category);
meta.push('**Readiness:** ' + ev.readiness_score + '/100');
out += meta.join('  ·  ') + '\n\n';

out += '## Observed Facts\n' + bullets(r.observed_facts) + '\n\n';
out += '## Working Hypothesis\n_This is a hypothesis, not a confirmed cause._\n\n'
     + (r.working_hypothesis || '_Not provided._') + '\n\n';
out += '## Recommended First Checks\n' + numbered(r.recommended_first_checks) + '\n\n';
out += '## Investigation Checklist\n' + checks(r.investigation_checklist) + '\n\n';
out += '## Still Missing\n' + bullets(r.missing_information) + '\n\n';
out += '## Next Best Question\n' + (r.next_best_question || '_Not provided._') + '\n';

if (ev.forced) {
  out += '\n---\n_Produced after ' + ev.iteration + ' rounds of questions without '
       + 'reaching the readiness threshold (score ' + ev.readiness_score
       + '/100). The gaps above are still open._\n';
}

return [{ json: { output: out } }];

