// DebugBuddy — Clarification Formatter (code, not AI)
// Mirrors the original prompt's rules exactly, but deterministically.
const sess = $('Session State').first().json;
const questions = ($json.output && $json.output.questions) || [];

const sd = $getWorkflowStaticData('global');
if (sd.sessions && sd.sessions[sess.sessionId]) {
  sd.sessions[sess.sessionId].completed = false;
}

if (questions.length === 0) {
  return [{ json: { output: 'I need a little more information, but I could not work out what to ask. Could you add any detail you have about where this happens and what you see?' } }];
}

const first = (questions[0].question || '').toLowerCase();
let opener;
if (first.includes('conflict') || first.includes('contradiction')) {
  opener = "There's a conflict in your report that I need to resolve before I can investigate.";
} else if (first.includes('multiple') || first.includes('separate issues')) {
  opener = 'Your report describes multiple separate issues.';
} else {
  opener = 'I need a little more information before I can turn this into an engineering report.';
}

const lines = questions.map((q, i) => (i + 1) + '. ' + q.question);
let out = opener + '\n\n' + lines.join('\n');
if (questions.length > 1) {
  out += '\n\nPlease answer these questions in order.';
}

return [{ json: { output: out } }];
